import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'archived';

interface Project {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
}

const STATUS_FILTERS: Array<{ value: ProjectStatus; label: string }> = [
  { value: 'active', label: 'Активные' },
  { value: 'paused', label: 'На паузе' },
  { value: 'archived', label: 'В архиве' },
];

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'default' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  archived: { label: 'В архиве', tone: 'default' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекст-лаборатория', used: 820, quota: 1000, status: 'active' },
  { id: 'p2', name: 'Поисковый индекс', used: 340, quota: 1000, status: 'active' },
  { id: 'p3', name: 'Аналитика воронки', used: 960, quota: 1200, status: 'paused' },
  { id: 'p4', name: 'Миграция биллинга', used: 120, quota: 600, status: 'archived' },
  { id: 'p5', name: 'Мобильный клиент', used: 450, quota: 900, status: 'active' },
  { id: 'p6', name: 'Импорт документов', used: 700, quota: 800, status: 'paused' },
  { id: 'p7', name: 'Очередь уведомлений', used: 180, quota: 500, status: 'active' },
  { id: 'p8', name: 'Экспорт отчётов', used: 540, quota: 700, status: 'archived' },
  { id: 'p9', name: 'Витрина метрик', used: 260, quota: 1000, status: 'active' },
  { id: 'p10', name: 'Служба вебхуков', used: 610, quota: 650, status: 'paused' },
  { id: 'p11', name: 'Песочница агентов', used: 90, quota: 400, status: 'active' },
  { id: 'p12', name: 'Архив логов', used: 480, quota: 500, status: 'archived' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(['active', 'paused']);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => (statuses.length === 0 ? [] : PROJECTS.filter((project) => statuses.includes(project.status))),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const removeStatus = (status: ProjectStatus) => {
    setStatuses((prev) => prev.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(STATUS_FILTERS.map((filter) => filter.value));
    setPage(1);
  };

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <header style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}>
        {statuses.length === 0 ? (
          <span style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-sans)' }}>Фильтры не выбраны</span>
        ) : (
          STATUS_FILTERS.filter((filter) => statuses.includes(filter.value)).map((filter) => (
            <JxChip key={filter.value} active removable onRemove={() => removeStatus(filter.value)}>
              {filter.label}
            </JxChip>
          ))
        )}
      </header>

      <JxDivider />

      {visible.length === 0 ? (
        <JxEmptyState
          title="Проектов не найдено"
          message="Под выбранные фильтры не попал ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {visible.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 16px',
                  background: 'var(--jx-surface)',
                  border: '1px solid var(--jx-border)',
                  borderRadius: 'var(--jx-r)',
                  boxShadow: 'var(--jx-shadow-sm)',
                }}
              >
                <JxProgressCircle value={project.used} max={project.quota} showValue />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div
                    style={{
                      color: 'var(--jx-text)',
                      fontFamily: 'var(--jx-font-sans)',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {project.name}
                  </div>
                  <div style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-mono)', fontSize: '12px' }}>
                    {project.used} / {project.quota}
                  </div>
                </div>
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </li>
            ))}
          </ul>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

